from pathlib import Path
import base64,gzip
ROOT=Path(__file__).resolve().parents[0]
FILES=[('app/src/main/java/com/orbital/iptv/recording/RecordingPublicStorage.kt', ''), ('app/src/main/java/com/orbital/iptv/recording/RecordingRepository.kt', ''), ('app/src/main/java/com/orbital/iptv/recording/RecordingService.kt', ''), ('app/src/main/java/com/orbital/iptv/recording/RecordingRepository.kt', ''), ('app/src/main/java/com/orbital/iptv/recording/RecordingService.kt', ''), ('app/src/main/java/com/orbital/iptv/recording/RecordingsActivity.kt', '')]
for rel,b64 in FILES:
 p=ROOT/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(gzip.decompress(base64.b64decode(b64)))
print('restored',len(FILES),'files')
